script:
(function () {
  'use strict';
  // Auto refinance savings: keep the current loan vs replace its remaining balance with a new loan.
  //   Current payment M = P x i / (1 - (1 + i)^-n), i = APR / 12 (M = P / n at 0%).
  //   Balance after k payments = P(1 + i)^k - M((1 + i)^k - 1) / i, worked out month by month,
  //   or entered directly with the months remaining.
  //   New loan = balance (+ fees when rolled in). Net savings = remaining payments on the current
  //   loan - (all new-loan payments + fees paid upfront).
  //   Break-even = first month in which the cumulative drop in payments covers the upfront fees.
  // Verified in Node (scratchpad tests/b3auto): $15,000 at 8.5% for 60 months = $307.75/mo; balance
  //   after 12 payments = $12,485.56 (closed form above); refinanced at 5% for 48 months = $287.53/mo;
  //   net savings with $300 upfront fees = $670.28 (= 48 x old payment - 48 x new payment - $300);
  //   $20.21/mo lower payments break even in month 15 (= ceil(300 / 20.21)); 0% rates give
  //   straight-line payments; a longer new term flags a higher total cost; no NaN on bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var last = null;

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  // Month-by-month payments of a loan; the final payment is trimmed to what is left owing.
  function amortize(loan, annualRate, months, payment) {
    var i = annualRate / 12, bal = loan, pays = [], totalInterest = 0;
    for (var m = 1; m <= months && bal > 0.005; m++) {
      var interest = bal * i;
      var pay = (m === months) ? bal + interest : Math.min(payment, bal + interest);
      bal -= pay - interest;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      pays.push(pay);
    }
    return { pays: pays, totalInterest: totalInterest };
  }

  function balanceAfter(loan, annualRate, payments, payment) {
    var i = annualRate / 12, bal = loan;
    for (var m = 1; m <= payments; m++) bal = bal * (1 + i) - payment;
    return Math.max(0, bal);
  }

  function sum(a) { return a.reduce(function (s, v) { return s + v; }, 0); }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function setText(id, text) { el(id).textContent = text; }

  function clearResults() {
    ['rfSavings', 'rfOldPayment', 'rfNewPayment', 'rfChange', 'rfBalanceOut', 'rfNewLoan', 'rfOldInterest',
     'rfNewInterest', 'rfOldTotal', 'rfNewTotal', 'rfBreakEven', 'rfOldLeft'].forEach(function (id) { setText(id, '–'); });
    el('rfWarn').hidden = true;
    el('rfSchedule').innerHTML = '';
    last = null;
  }

  function renderSchedule() {
    var body = el('rfSchedule');
    if (!last) { body.innerHTML = ''; return; }
    var html = [], n = Math.max(last.oldPays.length, last.newPays.length), oldY = 0, newY = 0, cum = -last.upfront;
    for (var m = 1; m <= n; m++) {
      var o = last.oldPays[m - 1] || 0, p = last.newPays[m - 1] || 0;
      oldY += o; newY += p; cum += o - p;
      if (m % 12 === 0 || m === n) {
        html.push('<tr><td>' + Math.ceil(m / 12) + '</td><td>' + money.format(oldY) + '</td><td>' +
          money.format(newY + (m <= 12 ? last.upfront : 0)) + '</td><td>' + money.format(cum) + '</td></tr>');
        oldY = 0; newY = 0;
      }
    }
    body.innerHTML = html.join('');
  }

  function update() {
    var byBalance = el('rfMode').value === 'balance';
    el('rfOrigWrap').hidden = byBalance;
    el('rfBalWrap').hidden = !byBalance;
    var oldRate = read('rfOldRate'), newRate = read('rfNewRate'), newTerm = read('rfNewTerm'),
        fees = read('rfFees', true), roll = el('rfRoll').checked;
    var error = el('rfError'), msg = '', balance, remaining, oldPayment;
    if (isNaN(oldRate) || oldRate < 0 || oldRate > 40) msg = 'Enter a current interest rate from 0% to 40%.';
    else if (byBalance) {
      balance = read('rfBalance'); remaining = read('rfRemaining');
      if (isNaN(balance) || balance <= 0) msg = 'Enter your current loan balance.';
      else if (isNaN(remaining) || remaining < 1 || remaining > 120 || remaining % 1 !== 0) msg = 'Enter 1 to 120 whole months remaining.';
    } else {
      var orig = read('rfOrigAmount'), term = read('rfOrigTerm'), made = read('rfMade', true);
      if (isNaN(orig) || orig <= 0) msg = 'Enter the original loan amount.';
      else if (isNaN(term) || term < 1 || term > 120 || term % 1 !== 0) msg = 'Enter an original term of 1 to 120 whole months.';
      else if (isNaN(made) || made < 0 || made % 1 !== 0 || made >= term) msg = 'Payments made must be a whole number less than the original term.';
    }
    if (!msg) {
      if (isNaN(newRate) || newRate < 0 || newRate > 40) msg = 'Enter a new interest rate from 0% to 40%.';
      else if (isNaN(newTerm) || newTerm < 1 || newTerm > 120 || newTerm % 1 !== 0) msg = 'Enter a new term of 1 to 120 whole months.';
      else if (isNaN(fees) || fees < 0) msg = 'Fees cannot be negative.';
    }
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }

    var oldR = oldRate / 100;
    if (byBalance) {
      oldPayment = monthlyPayment(balance, oldR, remaining);
    } else {
      oldPayment = monthlyPayment(orig, oldR, term);
      balance = balanceAfter(orig, oldR, made, oldPayment);
      remaining = term - made;
    }
    if (balance <= 0.005) { error.hidden = false; error.textContent = 'That loan is already paid off.'; clearResults(); return; }
    error.hidden = true;
    error.textContent = '';

    var oldLoan = amortize(balance, oldR, remaining, oldPayment);
    var newLoanAmt = balance + (roll ? fees : 0), upfront = roll ? 0 : fees;
    var newPayment = monthlyPayment(newLoanAmt, newRate / 100, newTerm);
    var newLoan = amortize(newLoanAmt, newRate / 100, newTerm, newPayment);
    var oldTotal = sum(oldLoan.pays), newTotal = sum(newLoan.pays) + upfront, savings = oldTotal - newTotal;
    var drop = oldPayment - newPayment, breakEven;
    if (drop <= 0.005) breakEven = 'No monthly saving';
    else if (upfront <= 0) breakEven = 'Right away';
    else {
      var cum = 0, found = 0, n = Math.max(oldLoan.pays.length, newLoan.pays.length);
      for (var m = 1; m <= n && !found; m++) {
        cum += (oldLoan.pays[m - 1] || 0) - (newLoan.pays[m - 1] || 0);
        if (cum >= upfront - 0.005) found = m;
      }
      breakEven = found ? 'Month ' + found + ' (' + duration(found) + ')' : 'Never';
    }

    setText('rfSavings', (savings < 0 ? '−' : '') + money.format(Math.abs(savings)));
    setText('rfSavingsLabel', savings < 0 ? 'Refinancing costs you more' : 'Total savings from refinancing');
    setText('rfOldPayment', money.format(oldPayment));
    setText('rfNewPayment', money.format(newPayment));
    setText('rfChange', (drop >= 0 ? money.format(drop) + ' lower' : money.format(-drop) + ' higher'));
    setText('rfBalanceOut', money.format(balance));
    setText('rfOldLeft', duration(remaining));
    setText('rfNewLoan', money.format(newLoanAmt));
    setText('rfOldInterest', money.format(oldLoan.totalInterest));
    setText('rfNewInterest', money.format(newLoan.totalInterest));
    setText('rfOldTotal', money.format(oldTotal));
    setText('rfNewTotal', money.format(newTotal));
    setText('rfBreakEven', breakEven);
    el('rfWarn').hidden = !(savings < 0 && drop > 0);
    last = { oldPays: oldLoan.pays, newPays: newLoan.pays, upfront: upfront };
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('rfForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
